import numpy as np
from packages.utils import *
import matplotlib.pyplot as plt
import h5py


def do_plot_2D(x, sim, title, xlabel="Frequency", ylabel="Efficiency"):
    plt.figure()
    plt.plot(x, sim['total_power_R'][:])
    plt.plot(x, sim['mode0R'][:], color='yellow')
    plt.plot(x, sim['mode1R'][:], color='red')
    plt.plot(x, sim['mode2R'][:], color='green')
    plt.plot(x, np.add(sim['mode1R'][:], sim['mode2R'][:]), color='purple')
    plt.xlabel(xlabel)
    plt.ylabel(ylabel)
    plt.title(title)
    plt.grid(True, which="both", alpha=0.3)
    plt.legend(["Total Power", "Fund. Mode", "1st Mode", "2nd Mode", "mode 1 + 2"])


