def do_plot_3D(X, Y, matrix, xlabel, ylabel, title):
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    ax.plot_surface(X, Y, matrix, cmap='viridis')

    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    ax.set_zlabel('Efficiency')
    plt.title(title)

    

def plot_3D(sim, xlabel, ylabel, title):
    with h5py.File("grating_coupler_results.h5", "r") as f: 
        X, Y = np.meshgrid(f[sim]['x_values'][:], f[sim]['y_values'][:])

        do_plot_3D(X, Y, f[sim]['total_power_R'][:], xlabel, ylabel, f"{title} Total Power")
        do_plot_3D(X, Y, f[sim]['mode0R'][:], xlabel, ylabel, f"{title} MODE 0R")
        do_plot_3D(X, Y, f[sim]['mode1R'][:], xlabel, ylabel, f"{title} MODE 1R")
        do_plot_3D(X, Y, f[sim]['mode2R'][:], xlabel, ylabel, f"{title} MODE 2R")


    plt.show()


